pub struct Data{pub(crate) sites:Vec<Site> ,pub(crate) source_text:Vec<String>,pub(crate) allow_used:Vec<AllowUse>,pub(crate) notes:Vec<String>,pub(crate) digests:BTreeMap<String,[u8;20]>,message_only:bool,doc_blocks:Option<Vec<crate::doc_snippets_policy::SummaryBlock>>}
impl Data{pub fn message_only(&self)->bool{self.message_only}pub fn doc_blocks(&self)->Option<&[crate::doc_snippets_policy::SummaryBlock]>{self.doc_blocks.as_deref()}pub fn sites(&self)->&[Site]{&self.sites}pub fn source_text(&self)->&[String]{&self.source_text}pub fn allow_used(&self)->&[AllowUse]{&self.allow_used}pub fn notes(&self)->&[String]{&self.notes}pub fn allow_source_digest(&self,rel:&str)->Option<&[u8;20]>{self.digests.get(rel)}}
