#[cfg(test)]mod allocation_controls{
 use super::*;
 fn source(text:String,mut consume:impl FnMut(&SourceFile)->Result<(),Failure>){let root=std::env::current_dir().unwrap().join("raw-tree-control-original");let budget=Budget::new(32*1024*1024).unwrap();crate::captured_raw_file::with_original_policy_file(&root,&root.join("code/control.dm"),text.into(),0,&budget,&mut|_,views|{consume(views.source_file()?)?;Ok(true)}).unwrap();}
 fn actual_error<T>(result:Result<T,Failure>)->io::Error{match result{Err(Failure::Operational(error))=>error,Err(Failure::Unsupported(message))=>panic!("unexpected semantic refusal: {message}"),Ok(_)=>panic!("controlled work unexpectedly completed")}}
 #[test]fn retained_fact_and_judge_growth_refuses_before_unfunded_output_and_recovers(){source("/obj/holder\n    latent_contents = TRUE\n/obj/machinery/control/machine_step()\n    return\n#define CAP_CONTROL (1<<4)\n/proc/tick()\n    if(world.time > next_tick)\n        return\n".into(),|file|{let roomy=Budget::new(8*1024*1024).unwrap();for which in 0..5{let denied=Budget::new(std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>()).unwrap();let mut keep=Operation{budget:&denied,poll:&||Ok(())};let mut temp=Operation{budget:&roomy,poll:&||Ok(())};let error=match which{0=>actual_error(crate::raw_tree_latent_policy::facts_of_using(file,&mut keep,&mut temp)),1=>actual_error(crate::raw_tree_pollers_policy::steps_using(file,&mut keep)),2=>actual_error(crate::raw_tree_cap_bits_policy::facts_of_using(file,&[],&[],&mut keep,&mut temp)),3=>actual_error(crate::raw_tree_cooldown_policy::judge_using(file,&crate::raw_tree_cooldown_policy::Patterns::new(),|_|false,&mut keep)),_=>actual_error(crate::raw_tree_latent_policy::judge_using(file,&HashSet::new(),&HashSet::new(),|_,_|false,&mut keep))};assert_eq!(error.kind(),io::ErrorKind::OutOfMemory);assert!(denied.denied());}
 let mut keep=Operation{budget:&roomy,poll:&||Ok(())};let mut temp=Operation{budget:&roomy,poll:&||Ok(())};assert!(!crate::raw_tree_latent_policy::facts_of_using(file,&mut keep,&mut temp)?.holders.is_empty());assert!(!crate::raw_tree_pollers_policy::steps_using(file,&mut keep)?.is_empty());assert!(crate::raw_tree_cap_bits_policy::assembly_entries(&crate::raw_tree_cap_bits_policy::facts_of_using(file,&[],&[],&mut keep,&mut temp)?)>0);assert!(!crate::raw_tree_cooldown_policy::judge_using(file,&crate::raw_tree_cooldown_policy::Patterns::new(),|_|false,&mut keep)?.is_empty());Ok(())});}
 #[test]fn large_fact_and_judge_loops_preserve_actual_mid_source_1450(){source(format!("machine_step(\n{}", "    no_matching_policy_here\n".repeat(4096)),|file|{for which in 0..5{let count=std::cell::Cell::new(0usize);let poll=||{let n=count.get()+1;count.set(n);if n==32{Err(io::Error::from_raw_os_error(1450))}else{Ok(())}};let budget=Budget::new(16*1024*1024).unwrap();let mut work=Operation{budget:&budget,poll:&poll};let mut temp=Operation{budget:&budget,poll:&||Ok(())};let error=match which{0=>actual_error(crate::raw_tree_latent_policy::facts_of_using(file,&mut work,&mut temp)),1=>actual_error(crate::raw_tree_pollers_policy::steps_using(file,&mut work)),2=>actual_error(crate::raw_tree_cap_bits_policy::facts_of_using(file,&[],&[],&mut work,&mut temp)),3=>actual_error(crate::raw_tree_latent_policy::judge_using(file,&HashSet::new(),&HashSet::new(),|_,_|false,&mut work)),_=>{let mut data=empty();let mut output=Output{data:&mut data,root:&budget,local:&budget,poll:&||Ok(()),failure:None};actual_error(crate::raw_tree_read_back_policy::judge_file_using(file,&crate::raw_tree_read_back_policy::ReadBack::new(),&BTreeSet::new(),&mut output,&mut work))}};assert_eq!(error.raw_os_error(),Some(1450));assert_eq!(count.get(),32);}Ok(())});}
}

