// Some old producers ask a direct ALLOW question despite their
// original registration metadata listing no aliases. Preserve each actual
// callback's delivered usage without changing the registry/unknown-name lint.
impl Policy{pub fn permits_used_allow(self,name:&str)->bool{self.metadata().allow.contains(&name)||(self==Self::ReadBack&&name=="read_back")||(self==Self::Expiry&&name=="cooldown")||(self==Self::NoticePublisher&&name=="notice_publisher")}}
#[cfg(test)]mod issued_allow_tests{use super::*;#[test]fn actual_read_back_callback_usage_does_not_expand_registered_or_other_policy_aliases(){assert!(Policy::ReadBack.metadata().allow.is_empty());assert!(Policy::ReadBack.permits_used_allow("read_back"));assert!(!Policy::ReadBack.permits_used_allow("scheduler"));assert!(!Policy::Cooldown.permits_used_allow("read_back"));assert!(Policy::Cooldown.permits_used_allow("cooldown"));for name in ["read_back_unported","sys_read_back","undeclared_read_back"]{assert!(!Policy::ReadBack.permits_used_allow(name));}}}

